import {displaySizeListing,orderedListing} from './cloud-display-size-fixture.mjs';
import {mountBuiltWorkspace} from './built-workspace.mjs';
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {JSDOM,VirtualConsole} from 'jsdom';
const html=await readFile(new URL('../../internal/webui/app/index.html',import.meta.url),'utf8');
// Header actions can be reordered; refresh tests target the action, not its ordinal position.
const tick=()=>new Promise(resolve=>setImmediate(resolve));
async function render(respond,search='',prepare=()=>{}){const dom=new JSDOM(html,{url:'http://localhost/cloud/files'+search,runScripts:'outside-only',pretendToBeVisual:true,virtualConsole:new VirtualConsole()}),requests=[];prepare(dom);dom.window.fetch=async(raw,init={})=>{requests.push({url:String(raw),method:init.method||'GET'});return respond(String(raw),init);};await mountBuiltWorkspace(dom);await tick();await tick();return {dom,requests};}
const listing=(directory,entries=[])=>orderedListing({directory,entries:entries.map((entry,index)=>({...entry,fs_id:entry.fs_id||String(index+1),size:String(entry.size),provider_size:String(entry.provider_size??entry.size),server_mtime:String(entry.server_mtime)})),queue_dir:'/queue',total:null,offset:0,observed_at_utc:'2026-11-03T01:00:00Z'});

test('row more actions disclose one row without requests and close on Escape or outside pointer',async()=>{
 const entries=[{id:'101',fs_id:'101',path:'/one.txt',name:'one.txt',directory:false,size:7,server_mtime:1},{id:'102',fs_id:'102',path:'/two.txt',name:'two.txt',directory:false,size:9,server_mtime:1}];
 const {dom,requests}=await render(async()=>({ok:true,json:async()=>listing('/',entries)}));
 try{const d=dom.window.document,buttons=[...d.querySelectorAll('[data-testid=cloud-row-more]')],panels=[...d.querySelectorAll('[data-testid=cloud-row-more-actions]')];
 assert.equal(buttons.length,2);assert.equal(panels.length,2);assert.ok(panels.every(p=>p.style.display==='none'));
 buttons[0].focus();buttons[0].click();await tick();assert.equal(buttons[0].getAttribute('aria-expanded'),'true');assert.equal(d.getElementById(buttons[0].getAttribute('aria-controls')),panels[0]);assert.notEqual(panels[0].style.display,'none');
 buttons[1].click();await tick();assert.equal(panels[0].style.display,'none');assert.equal(buttons[1].getAttribute('aria-expanded'),'true');
 panels[1].querySelector('button').focus();panels[1].dispatchEvent(new dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await tick();assert.equal(panels[1].style.display,'none');assert.equal(d.activeElement,buttons[1]);
 buttons[0].click();await tick();d.querySelector('h1').dispatchEvent(new dom.window.Event('pointerdown',{bubbles:true}));await tick();assert.equal(panels[0].style.display,'none');assert.equal(requests.length,1);assert.ok(requests.every(r=>r.method==='GET'));
 }finally{dom.window.close()}
});

test('row operation disclosure returns modal focus to its visible trigger and clears on refresh',async()=>{
 const {dom,requests}=await render(async()=>({ok:true,json:async()=>listing('/',[{id:'103',fs_id:'103',path:'/one.txt',name:'one.txt',directory:false,size:7,server_mtime:1}])}));
 try{const d=dom.window.document,more=d.querySelector('[data-testid=cloud-row-more]');assert.ok(more);more.focus();more.click();await tick();d.querySelector('[data-testid=cloud-file-rename]').click();await tick();await tick();
 assert.equal(more.getAttribute('aria-expanded'),'false');assert.ok(d.querySelector('[role=dialog]'));d.querySelector('[role=dialog]').dispatchEvent(new dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await tick();assert.equal(d.querySelector('[role=dialog]'),null);assert.equal(d.activeElement,more);assert.equal(requests.length,1);
 more.click();await tick();d.querySelector('[data-testid=cloud-files-refresh]').click();await tick();await tick();assert.equal(d.querySelector('[data-testid=cloud-row-more]').getAttribute('aria-expanded'),'false');assert.equal(d.querySelector('[data-testid=cloud-row-more-actions]').style.display,'none');assert.ok(requests.every(r=>r.method==='GET'));
 }finally{dom.window.close()}
});

test('other modal entries dismiss row disclosure without consuming the modal Escape',async()=>{
 for(const target of ['cloud-selected-move','cloud-file-info','cloud-mkdir']){
  const {dom,requests}=await render(async()=>({ok:true,json:async()=>listing('/',[{id:'104',fs_id:'104',path:'/one.txt',name:'one.txt',directory:false,size:7,server_mtime:1}])}));
  try{const d=dom.window.document;d.querySelector('[data-testid=cloud-select-item]').click();await tick();const more=d.querySelector('[data-testid=cloud-row-more]');more.click();await tick();const trigger=d.querySelector('[data-testid='+target+']');trigger.focus();trigger.click();await tick();await tick();assert.equal(more.getAttribute('aria-expanded'),'false',target);const dialog=d.querySelector('[role=dialog]');assert.ok(dialog,target);dialog.dispatchEvent(new dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await tick();assert.equal(d.querySelector('[role=dialog]'),null,target);assert.equal(d.activeElement,trigger,target);assert.ok(requests.every(r=>r.method==='GET'));
  }finally{dom.window.close()}
 }
});

test('row disclosure closes during a failed refresh and cache search never exposes mutations',async()=>{
 let finish,calls=0;const {dom}=await render(async()=>++calls===1?{ok:true,json:async()=>listing('/',[{id:'105',fs_id:'105',path:'/one.txt',name:'one.txt',directory:false,size:7,server_mtime:1}])}:new Promise(resolve=>finish=()=>resolve({ok:false,status:503,json:async()=>({message:'暂时无法读取目录'})})));
 try{const d=dom.window.document,more=d.querySelector('[data-testid=cloud-row-more]');more.click();await tick();d.querySelector('[data-testid=cloud-files-refresh]').click();await tick();assert.equal(more.disabled,true);assert.equal(more.getAttribute('aria-expanded'),'false');finish();await tick();await tick();assert.ok(d.querySelector('[role=alert]'));assert.equal(d.querySelector('[data-testid=cloud-row-more]').disabled,true);assert.equal(d.querySelector('[data-testid=cloud-row-more-actions]').style.display,'none');}finally{finish?.();dom.window.close()}
 const cached=await render(async raw=>({ok:true,json:async()=>filteredSearch(new URL(raw,'http://localhost').searchParams)}),new URL(savedSearch,'http://localhost').search);
 try{const d=cached.dom.window.document;assert.ok(d.querySelector('[data-testid=cloud-search-locate]'));assert.equal(d.querySelector('[data-testid=cloud-row-more]'),null);assert.equal(d.querySelector('[data-testid=cloud-file-delete]'),null);assert.ok(cached.requests.every(r=>r.method==='GET'));}finally{cached.dom.window.close()}
});

const filteredSearch=(params,override={})=>{const offset=Number(params.get('offset')||0);return {query:'lesson',scope:'/docs',kind:'file',entries:Array.from({length:offset?1:50},(_,i)=>({fs_id:String(offset+i+1),path:'/docs/lesson-'+(offset+i)+'.txt',name:'lesson-'+(offset+i)+'.txt',directory:false,size:'1',provider_mtime:'1'})),total:51,offset,next_offset:offset?null:50,cache_generation:'7',coverage:{status:'incomplete'},...override}};
const savedSearch='/cloud/files?dir=%2Fdocs&source=cache&q=lesson&scope=%2Fdocs&kind=file&offset=50&generation=7';
const locatedQuery='?'+new URLSearchParams({dir:'/docs',focus_id:'51',focus_path:'/docs/lesson-50.txt',focus_directory:'0',return_search:savedSearch});
const extraSearch=(q,override={})=>{const data=filteredSearch(q);return {...data,extensions:'pdf,mp4',modified_from:'100',modified_before:'200',entries:data.entries.map(e=>({...e,path:e.path.replace('.txt','.pdf'),name:e.name.replace('.txt','.pdf'),provider_mtime:'150'})),...override}};
test('search normalizes extension drafts and sends explicit UTC seconds only on submit',async()=>{
 const {dom,requests}=await render(async raw=>({ok:true,json:async()=>raw.includes('/search?')?extraSearch(new URL(raw,'http://localhost').searchParams):listing('/docs')}),'?dir=%2Fdocs');try{const d=dom.window.document;for(const [id,value] of [['cloud-cache-query','lesson'],['cloud-search-extensions','.PDF, .mp4, pdf'],['cloud-search-from','1970-01-01T00:01:40'],['cloud-search-before','1970-01-01T00:03:20']]){const input=d.querySelector('[data-testid='+id+']');assert.ok(input);input.value=value;input.dispatchEvent(new dom.window.Event('input',{bubbles:true}))}for(const [id,value] of [['cloud-search-scope','current'],['cloud-search-kind','file']]){const input=d.querySelector('[data-testid='+id+']');input.value=value;input.dispatchEvent(new dom.window.Event('change',{bubbles:true}))}await tick();assert.equal(requests.length,1);d.querySelector('[data-testid=cloud-cache-search]').click();await tick();await tick();const q=new URL(requests.at(-1).url,'http://localhost').searchParams;assert.equal(q.get('extensions'),'pdf,mp4');assert.equal(q.get('modified_from'),'100');assert.equal(q.get('modified_before'),'200');assert.match(d.querySelector('[data-testid=cloud-files-source-status]').textContent,/UTC/);assert.equal(d.querySelector('[role=alert]'),null)}finally{dom.window.close()}
});
