 for(const override of [{extensions:'txt'},{modified_from:'101'},{entries:[{fs_id:'1',path:'/docs/lesson.pdf',name:'lesson.pdf',directory:false,size:'1',provider_mtime:'0'}],total:1,next_offset:null}]){const {dom}=await render(async raw=>({ok:true,json:async()=>extraSearch(new URL(raw,'http://localhost').searchParams,override)}),'?source=cache&q=lesson&scope=%2Fdocs&kind=file&extensions=pdf%2Cmp4&modified_from=100&modified_before=200');try{assert.ok(dom.window.document.querySelector('[role=alert]'));assert.equal(dom.window.document.querySelectorAll('tbody tr[data-cloud-id]').length,0)}finally{dom.window.close()}}
