test('single cloud confirmations name the actual action and mark deletion as dangerous',async()=>{for(const [operation,label] of [['mkdir','确认新建'],['rename','确认重命名'],['move','确认移动'],['copy','确认复制'],['delete','确认删除']]){const {dom,requests}=await render(async()=>({ok:true,json:async()=>listing('/',[{id:'1',path:'/file.txt',name:'file.txt',directory:false,size:1024,server_mtime:1}])}));try{const d=dom.window.document;d.querySelector(operation==='mkdir'?'[data-testid=cloud-mkdir]':'[data-testid=cloud-file-'+operation+']').click();await tick();const button=d.querySelector('[data-testid=cloud-action-submit]');assert.equal(button.textContent,label);assert.equal(button.classList.contains('danger-button'),operation==='delete');assert.equal(button.disabled,true);assert.ok(requests.every(r=>r.method==='GET'));}finally{dom.window.close();}}});


test('returning to cloud tab refreshes idle rows but preserves a selected operation context',async()=>{
 let reads=0;const {dom}=await render(async()=>({ok:true,json:async()=>listing('/',[{id:'901',fs_id:'901',path:'/one.txt',name:'one.txt',directory:false,size:++reads,server_mtime:1}])}));
 try{const d=dom.window.document;dom.window.dispatchEvent(new dom.window.Event('focus'));await tick();assert.equal(reads,1,'initial focus does not reload');
 dom.window.dispatchEvent(new dom.window.Event('blur'));dom.window.dispatchEvent(new dom.window.Event('focus'));await tick();await tick();assert.equal(reads,2,'return reloads idle list');
 assert.ok(d.querySelector('[data-testid=cloud-select-item]'),d.body.textContent);d.querySelector('[data-testid=cloud-select-item]').click();await tick();dom.window.dispatchEvent(new dom.window.Event('blur'));dom.window.dispatchEvent(new dom.window.Event('focus'));await tick();await tick();assert.equal(reads,2,'selection prevents automatic reload');assert.equal(d.querySelector('[data-testid=cloud-select-item]').checked,true);assert.match(d.querySelector('[data-testid=cloud-return-notice]').textContent,/刷新/);
 d.querySelector('[data-testid=cloud-files-refresh]').click();await tick();await tick();assert.equal(reads,3);assert.equal(d.querySelector('[data-testid=cloud-return-notice]'),null);
 }finally{dom.window.close()}
});


