test('cleanup success revisions refresh rows without polling Baidu when unchanged or clearing selections',async()=>{
 const timers=new Map();let timerID=10000,revision='a'.repeat(64),reads=0;
 const {dom,requests}=await render(async raw=>raw==='/api/cloud/cleanup-revision'?{ok:true,json:async()=>({revision,observed_at_utc:'2026-11-06T02:00:00Z'})}:{ok:true,json:async()=>{reads++;return listing('/',[{id:'902',fs_id:'902',path:'/one.txt',name:'one.txt',directory:false,size:reads,server_mtime:1}])}},'',dom=>{const original=dom.window.setTimeout.bind(dom.window),clear=dom.window.clearTimeout.bind(dom.window);dom.window.setTimeout=(fn,delay,...args)=>{if(delay===2000){const id=++timerID;timers.set(id,fn);return id}return original(fn,delay,...args)};dom.window.clearTimeout=id=>{timers.delete(id);clear(id)}});
 const poll=async()=>{const [id,fn]=timers.entries().next().value||[];assert.ok(fn,'observer scheduled');timers.delete(id);fn();await tick();await tick();await tick()};
 try{const d=dom.window.document;assert.equal(reads,1);await poll();assert.equal(reads,2,'first observation reconciles startup race');await poll();assert.equal(reads,2,'unchanged local evidence does not read Baidu');revision='b'.repeat(64);await poll();assert.equal(reads,3,'any committed success refreshes');d.querySelector('[data-testid=cloud-select-item]').click();await tick();revision='c'.repeat(64);await poll();assert.equal(reads,3);assert.equal(d.querySelector('[data-testid=cloud-select-item]').checked,true);assert.match(d.querySelector('[data-testid=cloud-return-notice]').textContent,/清理/);dom.window.dispatchEvent(new dom.window.Event('pagehide'));assert.equal(timers.size,0);assert.ok(requests.every(r=>r.method==='GET'));}finally{dom.window.close()}
});


test('cleanup observation stops when hidden and ignores a late authentication failure after page restore',async()=>{
 const timers=new Map();let timerID=20000,finish,reads=0;
 const {dom,requests}=await render(async raw=>raw==='/api/cloud/cleanup-revision'?new Promise(resolve=>finish=resolve):{ok:true,json:async()=>{reads++;return listing('/')}},'',dom=>{const original=dom.window.setTimeout.bind(dom.window),clear=dom.window.clearTimeout.bind(dom.window);dom.window.setTimeout=(fn,delay,...args)=>{if(delay===2000){const id=++timerID;timers.set(id,fn);return id}return original(fn,delay,...args)};dom.window.clearTimeout=id=>{timers.delete(id);clear(id)}});
 try{Object.defineProperty(dom.window.document,'hidden',{configurable:true,value:true});dom.window.document.dispatchEvent(new dom.window.Event('visibilitychange'));assert.equal(timers.size,0);Object.defineProperty(dom.window.document,'hidden',{configurable:true,value:false});dom.window.document.dispatchEvent(new dom.window.Event('visibilitychange'));assert.equal(timers.size,1);const [id,fn]=timers.entries().next().value;timers.delete(id);fn();await tick();const request=requests.at(-1);assert.equal(request.url,'/api/cloud/cleanup-revision');dom.window.dispatchEvent(new dom.window.Event('pagehide'));dom.window.dispatchEvent(new dom.window.PageTransitionEvent('pageshow',{persisted:true}));await tick();await tick();assert.equal(reads,2);finish({ok:false,status:401});await tick();await tick();assert.equal(dom.window.document.querySelector('[data-testid=cloud-cleanup-sync-error]'),null);assert.equal(dom.window.document.querySelector('[role=alert]'),null);assert.equal(timers.size,1,'old request cannot cancel restored observer');}finally{finish?.({ok:false,status:503});dom.window.close()}
});

