test('cloud address bar groups history, parent and editable ancestor navigation',async()=>{
 const {dom,requests}=await render(async raw=>({ok:true,json:async()=>listing(new URL(raw,'http://localhost').searchParams.get('dir')||'/')}),'?dir=%2FA%2FB');
 try{const d=dom.window.document,bar=d.querySelector('[aria-label="网盘目录导航"]');assert.ok(bar);assert.equal(bar.querySelector('[data-testid=cloud-files-back]').disabled,true);assert.equal(bar.querySelector('[data-testid=cloud-files-forward]').disabled,true);assert.equal(bar.querySelector('[data-testid=cloud-files-up]').disabled,false);assert.ok(bar.querySelector('[aria-label="网盘路径"]'));bar.querySelector('[data-testid=cloud-address-edit]').click();await tick();const input=bar.querySelector('[data-testid=cloud-files-path]');assert.equal(d.activeElement,input);input.value='/draft';input.dispatchEvent(new dom.window.Event('input',{bubbles:true}));input.dispatchEvent(new dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));await tick();assert.equal(input.value,'/A/B');assert.equal(requests.length,1);const ancestor=[...bar.querySelectorAll('[aria-label="网盘路径"] button')].find(b=>b.textContent.trim()==='A');ancestor.click();await tick();await tick();assert.equal(input.value,'/A');assert.equal(bar.querySelector('[data-testid=cloud-files-back]').disabled,false);assert.equal(d.querySelectorAll('[data-testid=cloud-files-refresh]').length,1);}finally{dom.window.close()}
});


async function addressOpen(dom,path){const d=dom.window.document;d.querySelector('[data-testid=cloud-address-edit]').click();await tick();const input=d.querySelector('[data-testid=cloud-files-path]');input.value=path;input.dispatchEvent(new dom.window.Event('input',{bubbles:true}));d.querySelector('.cloud-pathbar').dispatchEvent(new dom.window.Event('submit',{bubbles:true,cancelable:true}));await tick();await tick();}
const historyTick=()=>new Promise(resolve=>setTimeout(resolve,35));
test('cloud navigation back and forward preserve known visits and trim a forward branch',async()=>{
 const {dom,requests}=await render(async raw=>({ok:true,json:async()=>listing(new URL(raw,'http://localhost').searchParams.get('dir')||'/')}));
 try{const d=dom.window.document,path=()=>d.querySelector('[data-testid=cloud-files-path]').value,back=()=>d.querySelector('[data-testid=cloud-files-back]'),forward=()=>d.querySelector('[data-testid=cloud-files-forward]');await addressOpen(dom,'/A');await addressOpen(dom,'/B');assert.equal(path(),'/B');const before=requests.length;back().click();back().click();await historyTick();await tick();assert.equal(path(),'/A');assert.equal(requests.length,before+1,'rapid second click cannot traverse again');assert.equal(forward().disabled,false);forward().click();await historyTick();await tick();assert.equal(path(),'/B');back().click();await historyTick();await tick();await addressOpen(dom,'/C');assert.equal(path(),'/C');assert.equal(forward().disabled,true);assert.equal(requests.at(-1).url.includes('dir=%2FC'),true);}finally{dom.window.close()}
});

