test('address bar can cancel a pending read without accepting its late result or recording a visit',async()=>{
 let finish,requestSignal;const {dom}=await render(async(raw,init)=>{const path=new URL(raw,'http://localhost').searchParams.get('dir')||'/';if(path==='/slow'){requestSignal=init.signal;return new Promise(resolve=>finish=resolve)}return {ok:true,json:async()=>listing(path)}});
 try{const d=dom.window.document;await addressOpen(dom,'/slow');const visits=dom.window.history.length;const cancel=d.querySelector('[data-testid=cloud-files-cancel-read]');assert.ok(cancel);cancel.click();await tick();assert.equal(requestSignal.aborted,true);assert.equal(d.querySelector('[data-testid=cloud-files-path]').value,'/');assert.match(d.querySelector('[role=alert]').textContent,/取消/);finish({ok:true,json:async()=>listing('/slow')});await tick();await tick();assert.equal(dom.window.history.length,visits);assert.equal(new URL(dom.window.location.href).searchParams.get('dir')||'/','/');assert.equal(d.querySelector('[data-testid=cloud-files-path]').value,'/');assert.equal(d.querySelector('[data-testid=cloud-files-back]').disabled,true);assert.equal(d.querySelector('[data-testid=cloud-files-cancel-read]'),null);}finally{finish?.({ok:false,status:503});dom.window.close()}
});


test('a cleanup observation does not restart a directory read the user cancelled',async()=>{
 let poll,finish;const {dom,requests}=await render(async raw=>{if(raw==='/api/cloud/cleanup-revision')return {ok:true,json:async()=>({revision:'a'.repeat(64),observed_at_utc:'2026-11-06T02:00:00Z'})};const path=new URL(raw,'http://localhost').searchParams.get('dir')||'/';if(path==='/slow')return new Promise(resolve=>finish=resolve);return {ok:true,json:async()=>listing(path)}},'',dom=>{const original=dom.window.setTimeout.bind(dom.window);dom.window.setTimeout=(fn,delay,...args)=>{if(delay===2000){poll=fn;return 30000}return original(fn,delay,...args)}});
 try{const d=dom.window.document;await addressOpen(dom,'/slow');d.querySelector('[data-testid=cloud-files-cancel-read]').click();await tick();finish({ok:true,json:async()=>listing('/slow')});await tick();await tick();const reads=requests.filter(r=>r.url.startsWith('/api/cloud?')).length;poll();await tick();await tick();assert.equal(requests.filter(r=>r.url.startsWith('/api/cloud?')).length,reads);assert.match(d.querySelector('[role=alert]').textContent,/取消/);}finally{finish?.({ok:false,status:503});dom.window.close()}
});
